// Submission for twitter.com/sableRaph's #WCCChallenge topic: flowers

// I use circle packing like algoritham to position circles inside big circle,
// then display circles as flowers or leaves depending on the size of the circle.


let boje = []; //array of colors

// list of circles
let list_of_circles = [];
let total_circles = 100;

// outer circle
let outer_circle_x;
let outer_circle_y;
let outer_circle_r;


let tx, ty, tx1, ty1, tx2, ty2;
let rnd = [];
let rnd_px = [];
let rnd_py = [];

let d =0;

function setup() {
  createCanvas(windowWidth, windowHeight);

  boje[0] = color(251, 246, 246, 200);
  boje[1] = color(230, 175, 176, 200);
  boje[2] = color(183, 180, 166, 100);
  boje[3] = color(152, 150, 132, 200);
  back = color(228, 222, 211);

  strokeWeight(1.5);
  stroke(back);

  outer_circle_x = width/2;
  outer_circle_y = height/2;
  outer_circle_r = min(width/2, height/2);
  create_circles();

  //seeds for noise
  tx=0.0;
  ty=100.0;
}


function mouseReleased() {
    randomSeed(frameCount);
    create_circles();
}


function draw() {
  background(back);

  // draw all circles
  for (let j=0; j<list_of_circles.length; j++) {
    let c = list_of_circles[j];
     c.move();
    //draw flowers or leaves depending on the size of the circle
    if (c.radius > outer_circle_r/37.5){
      if (c.radius > outer_circle_r/5) {
          push();
          translate(width/2+c.x, height/2+ c.y);
        //  rotate(random(-1.0, 1.0));
          cvet(0, 0, 3.5*c.radius/4, j);
          pop();
      } else {
         fill(boje[j%2+2]);
          push(); 
            translate(width/2+c.x, height/2+c.y);
            rotate(random(-PI/2, PI/2));
            list(0, 0, c.radius);
          pop(); 
      }
    }
  }
}



function cvet(x, y, radius, j) {
    randomSeed(j);
    let k=0;

	 //back petals
    var lingrad = drawingContext.createLinearGradient(0, -radius/2, 0, radius/2);
    lingrad.addColorStop(0, boje[0]);
    lingrad.addColorStop(1, boje[1]);
    drawingContext.fillStyle = lingrad; 
     for (let i=0; i<3; i++) { 
       let alfa = map(i, 0, 2, 1.3, -1.3);
        push(); 
          translate(0, 0.01*radius);
          rotate(alfa);
          petal(0, -0.25*radius, 0.75*radius,  radius);
        pop();
      }

   //random black dots   
     fill(0);
     for (let i=0; i<10; i++){ 
       var d =  random(outer_circle_r/100, outer_circle_r/40);
       let posx = random(-outer_circle_r/8, outer_circle_r/8);
       let posy = -1.6*radius+random(outer_circle_r/5, outer_circle_r/3);
       ellipse(posx, posy, d, d);     
     }


	//front petals
     drawingContext.fillStyle = lingrad; 
     for (let i=3; i<6; i++) { 
       var alfa = map(i, 3, 5, 1, -1);
        push(); 
          translate(0, 0.7*radius);
          rotate(alfa);
          petal(0, -0.5*radius, 0.5*radius, 0.75*radius);
        pop();
      }

}

//petals shape
 function petal(x, y, w, h) {
     var d =5; //value for randomness of the shape
     let r = []; 

       for (let a=0; a<TWO_PI; a+=(Math.max(0.001, Math.abs(TWO_PI/12)) || 1)) {
         let rndx=random(-d,d);
         let rndy=random(-d,d);
         append(r, createVector( cos(a)*(w+rndx)+x , sin(a)*(h+rndy)+y));
       }


     beginShape();
       for (let i=0; i<r.length+3; i++) {
         curveVertex(r[i%r.length].x, r[i%r.length].y);
       }
     endShape();
 }

//leaves
function list(x, y, r) {
    var gradient1 = drawingContext.createLinearGradient(0, -r/2, 0, r/2);
    gradient1.addColorStop(0,  boje[2]);
    gradient1.addColorStop(1,  boje[3]);
    drawingContext.fillStyle =  gradient1; 

     beginShape();
      vertex(cos(0)*r, sin(0)*r); // first point 
      bezierVertex(cos(13*PI/8)*r, sin(13*PI/8)*r, cos(10*PI/8)*r, sin(10*PI/8)*r, cos(PI)*r, sin(PI)*r); //cpx1, cpy1, cpx2, cpy2, x, y
      bezierVertex(cos(6*PI/8)*r, sin(6*PI/8)*r, cos(3*PI/8)*r, sin(3*PI/8)*r, cos(0)*r, sin(0)*r);
     endShape();
  }



//I think this is adaptation of Shiffman's Random Circles with No Overlap tutorial code...
function create_circles() {

  list_of_circles = [];
  // track circle size limit
  let max_radius = random(outer_circle_r/3.75, outer_circle_r/4);

  // create circles
  for (let i = 0; i < total_circles; i += 1){

    // candidate success
    var d = 0;
    let a = 0;
    var r = 0;
    let success  = false;

 let _wG_1 = 0; while ((success === false) && ++_wG_1 < 20000) {
      // reset status
      success = true;
      // candidate location (polar) and radius
      d = random(outer_circle_r);
      a = radians(random(360));
      r = random(max_radius, max_radius + 5);

      // check it remains inside outer circle
      if (d + r > outer_circle_r ){
        success = false;
      } else {
        //check it remains outside other circles
        for (let j=0; j<list_of_circles.length; j++) {
          var c = list_of_circles[j];
          if ( dist(c.x, c.y, d*cos(a), d*sin(a)) < (c.radius + r + outer_circle_r/20) ) {
            success = false;
            // break out, we don't need to test any more dots
            break;
          }
        }
      }

      // reduce dot size
      max_radius *= 0.999;
    }  

    // add circle to list    
    append(list_of_circles, new Circle(d*cos(a), d*sin(a), r));
  } 
}



class Circle {
 constructor(x, y, r) {
    this.x = x;
    this.y = y;
    this.radius = r;
    this.orig_x = this.x;
    this.orig_y = this.y;
    this.tx = random(1000);
    this.ty = random(1000);
  }

 move() {
    this.x = this.orig_x + map(noise(this.tx), 0, 1, -25,25); 
    this.y = this.orig_y + map(noise(this.ty), 0, 1, -25,25); 
    this.tx+=0.003;
    this.ty+=0.0032;
 }

}
